<script setup>defineProps({modelValue:[String,Number],items:{default:()=>[]},fullWidth:Boolean});defineEmits(['update:modelValue'])</script><template><div class="segments" :class="{full:fullWidth}"><button v-for="i in items" :key="i.value" type="button" :class="{on:modelValue===i.value}" @click="$emit('update:modelValue',i.value)">{{i.label}}</button></div></template><style scoped>.segments{display:inline-flex;padding:3px;border:1px solid var(--border-subtle);border-radius:var(--radius-pill);background:var(--progress-none)}.full{display:flex}.full button{flex:1}button{min-height:36px;padding:0 14px;border:0;border-radius:var(--radius-pill);background:transparent;color:var(--text-muted);font:600 13px var(--font-core)}button.on{background:var(--surface-secondary);color:var(--text-primary);box-shadow:var(--elev-1)}</style>
